293→	// Skip during rebase, cherry-pick, or revert operations
294→	// These are replaying existing commits and should not be linked to agent sessions
295→	if isGitSequenceOperation(ctx) {
296→		logging.Debug(logCtx, "prepare-commit-msg: skipped during git sequence operation",
297→			slog.String("strategy", "manual-commit"),
298→			slog.String("source", source),
299→		)
300→		return nil
301→	}
302→
303→	// Skip for merge and squash sources
304→	// These are auto-generated messages - not from Claude sessions
305→	switch source {
306→	case "merge", "squash":
307→		logging.Debug(logCtx, "prepare-commit-msg: skipped for source",
308→			slog.String("strategy", "manual-commit"),
309→			slog.String("source", source),
310→		)
311→		return nil
312→	}
313→
314→	// Handle amend (source="commit") separately: preserve or restore trailer
315→	if source == "commit" {
316→		return s.handleAmendCommitMsg(ctx, commitMsgFile)
317→	}
318→
319→	repo, err := OpenRepository(ctx)
320→	if err != nil {
321→		return nil //nolint:nilerr // Hook must be silent on failure
322→	}
323→
324→	worktreePath, err := paths.WorktreeRoot(ctx)
325→	if err != nil {
326→		return nil //nolint:nilerr // Hook must be silent on failure
327→	}
328→
329→	// Find all active sessions for this worktree
330→	// We match by worktree (not BaseCommit) because the user may have made
331→	// intermediate commits without entering new prompts, causing HEAD to diverge
332→	sessions, err := s.findSessionsForWorktree(ctx, worktreePath)
