334→		// No active sessions or error listing - silently skip (hooks must be resilient)
335→		logging.Debug(logCtx, "prepare-commit-msg: no active sessions",
336→			slog.String("strategy", "manual-commit"),
337→			slog.String("source", source),
338→		)
339→		return nil //nolint:nilerr // Intentional: hooks must be silent on failure
340→	}
341→
342→	// Fast path: when an agent is committing (ACTIVE session + no TTY), skip
343→	// content detection and interactive prompts. The agent can't respond to TTY
344→	// prompts and the content detection can miss mid-session work (no shadow
