361→			slog.String("strategy", "manual-commit"),
362→			slog.String("source", source),
363→			slog.Int("sessions_found", len(sessions)),
364→		)
365→		return nil
366→	}
367→
368→	// Read current commit message
369→	content, err := os.ReadFile(commitMsgFile) //nolint:gosec // commitMsgFile is provided by git hook
370→	if err != nil {
371→		return nil //nolint:nilerr // Hook must be silent on failure
372→	}
