802→// FlattenTree recursively flattens a tree into a map of full paths to entries.
803→func FlattenTree(repo *git.Repository, tree *object.Tree, prefix string, entries map[string]object.TreeEntry) error {
804→	for _, entry := range tree.Entries {
805→		fullPath := entry.Name
806→		if prefix != "" {
807→			fullPath = prefix + "/" + entry.Name
808→		}
809→
810→		if entry.Mode == filemode.Dir {
811→			// Recurse into subtree
812→			subtree, err := repo.TreeObject(entry.Hash)
813→			if err != nil {
814→				return fmt.Errorf("failed to get subtree %s: %w", fullPath, err)
815→			}
816→			if err := FlattenTree(repo, subtree, fullPath, entries); err != nil {
817→				return err
818→			}
819→		} else {
820→			entries[fullPath] = object.TreeEntry{
821→				Name: fullPath,
822→				Mode: entry.Mode,
823→				Hash: entry.Hash,
824→			}
825→		}
826→	}
827→	return nil
828→}
