836→// createBlobFromFile creates a blob object from a file in the working directory.
837→func createBlobFromFile(repo *git.Repository, filePath string) (plumbing.Hash, filemode.FileMode, error) {
838→	info, err := os.Stat(filePath)
839→	if err != nil {
840→		return plumbing.ZeroHash, 0, fmt.Errorf("failed to stat file: %w", err)
841→	}
842→
843→	// Determine file mode
844→	mode := filemode.Regular
845→	if info.Mode()&0o111 != 0 {
846→		mode = filemode.Executable
847→	}
848→	if info.Mode()&os.ModeSymlink != 0 {
849→		mode = filemode.Symlink
850→	}
851→
852→	// Read file contents
853→	content, err := os.ReadFile(filePath) //nolint:gosec // filePath comes from walking the repository
854→	if err != nil {
855→		return plumbing.ZeroHash, 0, fmt.Errorf("failed to read file: %w", err)
856→	}
857→
858→	// Create blob object
859→	obj := repo.Storer.NewEncodedObject()
860→	obj.SetType(plumbing.BlobObject)
861→	obj.SetSize(int64(len(content)))
862→
863→	writer, err := obj.Writer()
864→	if err != nil {
865→		return plumbing.ZeroHash, 0, fmt.Errorf("failed to get object writer: %w", err)
866→	}
867→
868→	_, err = writer.Write(content)
