1044→// buildTreeObject recursively builds tree objects from a treeNode.
1045→func buildTreeObject(repo *git.Repository, node *treeNode) (plumbing.Hash, error) {
1046→	var treeEntries []object.TreeEntry
1047→
1048→	// Add files
1049→	treeEntries = append(treeEntries, node.files...)
1050→
1051→	// Recursively build subtrees
1052→	for name, subnode := range node.entries {
1053→		subHash, err := buildTreeObject(repo, subnode)
1054→		if err != nil {
