1058→			Name: name,
1059→			Mode: filemode.Dir,
1060→			Hash: subHash,
1061→		})
1062→	}
1063→
1064→	// Sort entries (git requires sorted entries)
1065→	sortTreeEntries(treeEntries)
1066→
1067→	// Create tree object
