1069→
1070→	obj := repo.Storer.NewEncodedObject()
1071→	if err := tree.Encode(obj); err != nil {
1072→		return plumbing.ZeroHash, fmt.Errorf("failed to encode tree: %w", err)
1073→	}
1074→
1075→	hash, err := repo.Storer.SetEncodedObject(obj)
1076→	if err != nil {
1077→		return plumbing.ZeroHash, fmt.Errorf("failed to store tree: %w", err)
