1083→// sortTreeEntries sorts tree entries in git's required order.
1084→// Git sorts tree entries by name, with directories having a trailing /
1085→func sortTreeEntries(entries []object.TreeEntry) {
1086→	sort.Slice(entries, func(i, j int) bool {
1087→		nameI := entries[i].Name
1088→		nameJ := entries[j].Name
1089→		if entries[i].Mode == filemode.Dir {
1090→			nameI += "/"
1091→		}
1092→		if entries[j].Mode == filemode.Dir {
1093→			nameJ += "/"
1094→		}
1095→		return nameI < nameJ
