294→// getSessionsBranchRef returns the sessions branch parent commit hash and root tree hash
295→// without flattening the tree.
296→func (s *GitStore) getSessionsBranchRef() (plumbing.Hash, plumbing.Hash, error) {
297→	refName := plumbing.NewBranchReferenceName(paths.MetadataBranchName)
298→	ref, err := s.repo.Reference(refName, true)
299→	if err != nil {
300→		return plumbing.ZeroHash, plumbing.ZeroHash, fmt.Errorf("failed to get sessions branch reference: %w", err)
301→	}
302→
303→	parentCommit, err := s.repo.CommitObject(ref.Hash())
304→	if err != nil {
305→		return plumbing.ZeroHash, plumbing.ZeroHash, fmt.Errorf("failed to get commit object: %w", err)
306→	}
307→
308→	return ref.Hash(), parentCommit.TreeHash, nil
309→}
